scwin.hasClass = function(id) {
    return WebSquare.wUnit.getJq(id).hasClass('gridBodyDefault_checkcombobox');
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 0. select 컬럼의 속성을 설정한다.(샘플은 설정됨)
    //0. Set the attributes of the select column (samples are set).
    // verify step 0. colMerge = true, colMergeEdit = false, viewType = icon
    //0. colMerge = true, colMergeEdit = false, viewType = icon
    // Test step 1. 샘플파일 실행 후 2번째항목인 checkcombobox의 2번째 row의 값을 2에서 1로 변경(2를 체크해제하고 1을 체크)하고 다른 컬럼을 선택한다.
    //1. After running the sample file, change the value of the second row of checkcombobox from 2 to 1 (uncheck 2 and check 1) and select another column.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_5_cell_2_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_wq_uuid_5___checkcombobox_col2_itemTable_1_checkbox').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_wq_uuid_5___checkcombobox_col2_itemTable_0_checkbox').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_5_cell_0_2').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    // verify step 1. 상위의 1값으로 merge되어 보여진다.(역삼각형도 merge되어짐)(이전에는 역삼각형이 남아있었음)
    //1. Merge to the top 1 value (inverted triangles are also merged)(Previously the inverted triangle remained)
    WebSquare.wUnit.addCommand("assert", "scwin.hasClass('wq_uuid_5_cell_2_1')", "false");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function unitTest
    //Created By: Sang.do
    //Created By: 29-Jan-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
